-- Admakai approved portfolio videos: categories, works with sample case studies, service links.
-- Safe to run more than once (upserts by slug).

insert into work_categories (slug, name, sort_order) values
  ('ai-commercials', 'AI Commercials', 1),
  ('brand-films', 'Brand Films', 2),
  ('ugc', 'UGC Ads', 3),
  ('cgi-product', 'CGI Product', 4),
  ('product-shoots', 'Product Shoots', 5),
  ('fashion', 'Fashion', 6),
  ('ai-twins', 'AI Twins and Presenters', 7),
  ('motion', 'Motion and Explainers', 8),
  ('social-ads', 'Social Ads', 9),
  ('characters', 'Characters and Mascots', 10)
on conflict (slug) do update set name = excluded.name, sort_order = excluded.sort_order;

with tpl(cat, problems, solutions, steps, tools) as (values
  ('ai-commercials', '["A live shoot for {S} would need a location, cast, crew and several days, which makes a short commercial costly.", "The ad had to feel warm and real, not like stock footage stitched together.", "The same story had to work on YouTube, Facebook and in-store screens."]'::jsonb, '["We wrote a short story around {S} and planned every shot as a storyboard before any generation.", "We built the cast and the {L} with AI, keeping faces, clothes and the product consistent from shot to shot.", "We edited, graded and mixed it like any commercial, so it plays like a filmed ad."]'::jsonb, '["Brief and script", "Look, cast and storyboard", "Shot generation and selects", "Edit, grade and sound"]'::jsonb, '["AI image generation", "AI video generation", "Edit and colour grade", "Sound design"]'::jsonb),
  ('brand-films', '["Telling the story of {S} usually means a large crew and many locations.", "The film had to hold attention for more than a minute, so every scene needed a reason to be there.", "It had to sound and feel like the brand, not like a generic AI showreel."]'::jsonb, '["We built the film around one clear idea and a script written for the voice of the brand.", "We generated {L} with AI and kept the main character consistent across every scene.", "We cut it with music, subtitles and sound design so it plays well with or without audio."]'::jsonb, '["Idea and script", "Character and world design", "Scene generation", "Edit, subtitles and sound"]'::jsonb, '["AI video generation", "Character consistency", "Edit and colour grade", "Subtitles and sound design"]'::jsonb),
  ('ugc', '["Real creators for {S} take time to book, ship product to and brief.", "The first second decides whether people keep watching, so the hook had to land fast.", "The ad had to look like a phone video, not a polished commercial."]'::jsonb, '["We wrote a hook first, then a short problem, product and reaction script.", "We made an AI creator and shot style that feels like {L}.", "We added captions and quick cuts in the native style of Reels and TikTok."]'::jsonb, '["Hook and script", "AI creator and look", "Generation", "Captions and cut"]'::jsonb, '["AI creator", "AI video generation", "Captions", "Mobile first edit"]'::jsonb),
  ('cgi-product', '["Shooting {S} with real props and lighting needs a studio and a lot of retakes.", "The product label and shape had to stay exactly right in every frame.", "The reel had to stop the scroll in under three seconds."]'::jsonb, '["We designed a {L} scene that tells the product story without words.", "We kept the real product from the brand reference and built the world around it.", "We timed the camera move and the reveal to land in the first seconds."]'::jsonb, '["Product reference and idea", "Scene and lighting design", "CGI style generation", "Motion, grade and export"]'::jsonb, '["AI image generation", "AI video generation", "Product consistency", "Colour grade"]'::jsonb),
  ('product-shoots', '["A studio day for {S} means props, a photographer and a long retouch.", "The product had to look premium while keeping its real label and colours.", "The brand needed many angles and moods for social, quickly."]'::jsonb, '["We placed {S} in a {L} set made with AI.", "We kept the product true to the photo the brand gave us.", "We added gentle motion so the shot works as a post and as a short video."]'::jsonb, '["Product photo and mood", "Set design", "Generation and selection", "Motion and final export"]'::jsonb, '["AI product photography", "AI image to video", "Retouch", "Colour grade"]'::jsonb),
  ('fashion', '["A fashion shoot needs models, locations, a crew and good weather on the same day.", "Every look needed the same face and the real garment, with no changes to the clothes.", "The brand needed many vertical reels for one collection."]'::jsonb, '["We cast one consistent AI model and kept the same face across every look.", "We kept each garment exactly as the product photo, with fabric and fit intact.", "We set the looks in {L} with a premium fashion camera style."]'::jsonb, '["Model and garment references", "Location and styling", "Reel generation", "Grade and export"]'::jsonb, '["AI model", "Garment consistency", "AI video generation", "Fashion grade"]'::jsonb),
  ('ai-twins', '["Filming {S} means booking a person, a studio and a crew every time something changes.", "Long talks to camera need natural face, lip and hand movement to stay believable.", "The content had to be updated often without reshooting."]'::jsonb, '["We built an AI twin or presenter from approved references.", "We placed the presenter in {L} and matched voice and lip sync.", "We kept the script easy to change, so new versions do not need a shoot."]'::jsonb, '["Script", "Presenter and voice", "Generation and lip sync", "Edit and subtitles"]'::jsonb, '["AI presenter", "Voice and lip sync", "AI video generation", "Subtitles"]'::jsonb),
  ('motion', '["Explaining {S} in words alone takes too long.", "The message had to be clear in seconds, even with the sound off.", "It had to match the brand colours and type."]'::jsonb, '["We cut the message down to one idea per scene.", "We designed the scenes as {L}.", "We timed the motion to the voice or music so each point lands."]'::jsonb, '["Message and script", "Style frames", "Animation", "Sound and export"]'::jsonb, '["Motion design", "Kinetic type", "Illustration", "Sound design"]'::jsonb),
  ('social-ads', '["The brand needed fresh posts for {S} every week, faster than a photo shoot allows.", "Each post had to carry one clear message, with Bangla copy where needed.", "The team wanted versions to test which design gets more response."]'::jsonb, '["We designed the post on a {L} with the product as the hero.", "We kept the copy short and the product label real.", "We made the layout easy to remix into more versions."]'::jsonb, '["Message and copy", "Design", "Light motion", "Versions and export"]'::jsonb, '["AI product imagery", "Graphic design", "Light motion", "Bangla typography"]'::jsonb),
  ('characters', '["{SC} needed a character people remember, not just a logo.", "The character had to look the same in every scene and every post.", "It had to work for kids and families without feeling cheap."]'::jsonb, '["We designed a character with a clear personality and a simple shape.", "We built scenes like {L} around the character.", "We kept a character sheet so future content stays on model."]'::jsonb, '["Character idea", "Design and sheet", "Scene generation", "Edit and sound"]'::jsonb, '["Character design", "AI image generation", "AI video generation", "Sound design"]'::jsonb)
),
