x as (
  select v.*, t.problems, t.solutions, t.steps, t.tools,
    case v.aspect when '16:9' then 'landscape' when '9:16' then 'vertical' when '1:1' then 'square' else 'portrait' end as aw,
    upper(left(v.subject,1)) || substr(v.subject,2) as subject_cap
  from v join tpl t on t.cat = v.cat
)
insert into works (slug, title, vimeo_id, aspect, duration_sec, category_id, client_name, industry, year,
  short_description, tags, featured, published, sort_order, case_study)
select x.slug, x.title, substring(x.vimeo_url from '([0-9]+)$'), x.aspect, x.duration_sec, c.id, x.client_name, x.industry, 2026,
  x.short_description, array[c.name, x.industry], x.featured, true, x.sort_order,
  jsonb_build_object(
    'is_sample', true,
    'overview', x.short_description || ' Everything in it was made with AI, with no shoot day.',
    'problems', replace(replace(replace(x.problems::text, '{SC}', x.subject_cap), '{S}', x.subject), '{L}', x.look)::jsonb,
    'solutions', replace(replace(replace(x.solutions::text, '{SC}', x.subject_cap), '{S}', x.subject), '{L}', x.look)::jsonb,
    'process', jsonb_build_array(
      jsonb_build_object('title', x.steps->>0, 'body', 'We agreed the goal, the audience and the one message the video must carry.'),
      jsonb_build_object('title', x.steps->>1, 'body', 'We fixed the look, references and characters before generating anything.'),
      jsonb_build_object('title', x.steps->>2, 'body', 'We generated many takes and kept only the shots that hold up frame by frame.'),
      jsonb_build_object('title', x.steps->>3, 'body', 'We finished it like a normal production: edit, colour, sound and export for each platform.')),
    'tools', x.tools,
    'deliverables', jsonb_build_array(x.duration_sec || ' second ' || x.aw || ' video (' || x.aspect || ')'),
    'result', 'A finished ' || x.aw || ' video for ' || x.subject || ', ready to post, made without a camera crew.',
    'metrics', '[]'::jsonb,
    'testimonial', null)
from x join work_categories c on c.slug = x.cat
on conflict (slug) do update set
  title = excluded.title, vimeo_id = excluded.vimeo_id, aspect = excluded.aspect, duration_sec = excluded.duration_sec,
  category_id = excluded.category_id, client_name = excluded.client_name, industry = excluded.industry, year = excluded.year,
  short_description = excluded.short_description, tags = excluded.tags, featured = excluded.featured,
  published = excluded.published, sort_order = excluded.sort_order, case_study = excluded.case_study;

